                       "5) Must be PROBABLE that the resource generates future benefits - if benefit expires WITHIN current period, it\u0027s an EXPENSE not an asset (e.g. dealer\u0027s machinery sold in same period = expense; unsold stock = closing stock/asset).",
                       "6) Must have a COST or VALUE that can be measured RELIABLY; if flow beyond current period is IMPROBABLE, treat as expense not asset."
