                       "2) REASON 2: Enterprises operate in DIVERSE situations - impossible to develop a SINGLE set of policies applicable to ALL enterprises for ALL time.",
                       "3) Even in areas COVERED by a standard, AS PERMIT MORE THAN ONE policy - differences in policy lead to DIFFERENCES in reported information even for the SAME underlying transactions.",
                       "4) The qualitative characteristic of COMPARABILITY therefore SUFFERS due to policy diversity. Since uniformity is impossible, mere compliance with standards is NOT enough - AS 1 requires DISCLOSURE of significant policies actually adopted, so users can make necessary ADJUSTMENTS in their analysis."
