                       "1) Foreign currency monetary assets (bank balance, debtors) and liabilities (creditors) are initially recognised using rate on TRANSACTION DATE; restated on BALANCE SHEET DATE using closing rate. The difference = exchange gain/loss, recognised in Statement of Profit \u0026 Loss.",
                       "2) For CASH and CASH EQUIVALENTS in foreign currency: recognised similarly and restated in balance sheet at closing rate. HOWEVER, the change in cash/cash equivalents due to exchange gains/losses is NOT a cash flow.",
                       "3) Therefore, net increase/decrease in cash \u0026 cash equivalents in the CFS is stated EXCLUSIVE of exchange gains/losses.",
                       "4) The resultant DIFFERENCE between cash \u0026 cash equivalents per CFS and per balance sheet is RECONCILED in a NOTE to the CFS."
