        "title":  "Define Segment Result, Segment Assets (including exclusions) and Segment Liabilities (including exclusions).",
        "subtitle":  "Segment Result, Segment Assets and Segment Liabilities",
        "prompt":  "Reference? Key points? Exam keywords?",
