                       "2) Where interest IS included in inventory cost, and those inventories are part of segment assets, such interest SHOULD be treated as segment expense.",
                       "3) In this case, the AMOUNT of such interest and the FACT that segment result was arrived at after considering such interest must be DISCLOSED BY WAY OF A NOTE to the segment result."
