        "chapter":  "Chapter 4 Unit 3: Accounting Standard 17 - Segment Reporting",
        "title":  "What is the starting point for allocating revenue, expense, assets and liabilities to segments, and what is the timing rule regarding intra-enterprise eliminations?",
        "subtitle":  "Allocation of Items to Segments",
