                       "2) However, an internal allocation basis may be deemed ARBITRARY externally, or an enterprise may choose NOT to allocate certain items internally even though a reasonable basis exists - in such cases, allocation follows the AS 17 DEFINITIONS of segment revenue/expense/assets/liabilities (not internal reporting).",
                       "3) TIMING: Segment revenue, expense, assets and liabilities are determined BEFORE intra-enterprise balances/transactions are eliminated in preparing enterprise FS - EXCEPT to the extent such intra-enterprise items are WITHIN A SINGLE SEGMENT.",
